mapper.select:



        (t.code LIKE CONCAT('%', #{keyword}, '%') OR t.name LIKE CONCAT('%', #{keyword}, '%'))

    AND t.mold_type = #{moldType}
    AND t.status = #{status}

        AND EXISTS (SELECT 1 FROM mes_mold_product p WHERE p.mold_id = t.id AND p.material_id = #{productId})


        AND t.design_life IS NOT NULL AND t.used_count * 100 >= t.design_life * t.warn_ratio AND t.status <> 'SCRAPPED'


ORDER BY t.code
